#include <bits/stdc++.h>
using namespace std;
#define int long long
#define all(x) (x).begin(),(x).end()

int get(int z, int y, int x)
{
    if (y < z) swap(y, z);
    if (x < y) swap(x, y);
    if (y < z) swap(y, z);
    return max(6 * x, max(4 * (x + y), 3 * (x + y + z)));
}

signed main() {
	// your code goes here
    int t;
    cin >> t;
    while (t--)
    {
        int n;
        cin >> n;
        vector<int> a(3 * n);
        for (int &i : a) cin >> i;
        sort(all(a));
        vector<int> prefix(3 * n + 1);
        for (int i = 1 ; i <= 3 * n ; ++i)
            prefix[i] = prefix[i - 1] + a[i - 1];
        auto check = [&](const int l, const int r) -> int{
            int len = (r - l + 1);
            int lo = 1, hi = len / 3;
            int ans = 3 * (prefix[r + 1] - prefix[l]);
            ans = max(ans, 4 * (prefix[r + 1] - prefix[r + 1 - 2 * len / 3]));
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                ans = max(ans, 4 * (prefix[r + 1] - prefix[r - 2 * mid + 1]) + 3 * (prefix[r - 2 * mid + 1] - prefix[l + mid]));
                if (a[r - 2 * mid + 1] + a[r - 2 * mid + 2] >= 3 * a[l + mid - 1]){
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            return ans;
        };
        int ans = check(0, 3 * n - 1);
        int curr = 0;
        for (int i = 1; i <= n; ++i)
        {
            curr += 6 * a[3 * n - i];
            ans = max(ans, curr + check(2 * i, 3 * n - i - 1));
        }
        cout << ans << "\n";
    }
}
